<?php
namespace App\Services\Warehouse\Finance;
use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class WarehouseFinanceService{
 public function generateInvoice(string $grId,object $user):object{return DB::transaction(function()use($grId,$user){$gr=DB::table('wh_sales_goods_receipts')->lockForUpdate()->where('id',$grId)->first();if(!$gr||$gr->status!=='completed')throw ValidationException::withMessages(['goods_receipt_id'=>'GR harus completed sebelum invoice dibuat.']);$old=DB::table('wh_sales_invoices')->where('goods_receipt_id',$grId)->first();if($old)return $old;$so=DB::table('wh_sales_orders')->where('id',$gr->sales_order_id)->first();if(!$so)throw ValidationException::withMessages(['sales_order_id'=>'Sales Order sumber tidak ditemukan.']);$customer=DB::table('wh_customers')->where('id',$gr->customer_id)->first();$id=(string)Str::ulid();$due=now()->addDays((int)($customer->credit_term_days??0))->toDateString();$items=DB::table('wh_sales_goods_receipt_items as gi')->join('wh_sales_delivery_order_items as di','di.id','=','gi.delivery_order_item_id')->leftJoin('wh_sales_order_items as si','si.id','=','di.sales_order_item_id')->where('gi.goods_receipt_id',$grId)->select('gi.*','di.sales_order_item_id','si.unit_price','si.discount_amount','si.tax_amount','si.line_total','si.ordered_qty_base')->get();$subtotal=$discount=$tax=$grand=$cogs=0.0;DB::table('wh_sales_invoices')->insert(['id'=>$id,'invoice_number'=>$this->number('WH-SINV'),'goods_receipt_id'=>$grId,'sales_order_id'=>$gr->sales_order_id,'warehouse_id'=>$gr->warehouse_id,'customer_id'=>$gr->customer_id,'invoice_date'=>now()->toDateString(),'due_date'=>$due,'currency_code'=>$so->currency_code??'IDR','status'=>'issued','idempotency_key'=>'goods-receipt:'.$grId,'issued_at'=>now(),'issued_by_user_id'=>$user->id,'created_at'=>now(),'updated_at'=>now()]);foreach($items as $x){$qty=(float)$x->received_qty_base;$ordered=max((float)($x->ordered_qty_base??$qty),0.0001);$unit=(float)($x->unit_price??0);$disc=(float)($x->discount_amount??0)*($qty/$ordered);$tx=(float)($x->tax_amount??0)*($qty/$ordered);$line=max(0,$qty*$unit-$disc+$tx);$unitCost=$this->resolveUnitCost($gr->warehouse_id,$x->sku_id,$gr->sales_order_id);$lineCogs=$qty*$unitCost;$margin=$line-$lineCogs;$subtotal+=$qty*$unit;$discount+=$disc;$tax+=$tx;$grand+=$line;$cogs+=$lineCogs;DB::table('wh_sales_invoice_items')->insert(['id'=>(string)Str::ulid(),'sales_invoice_id'=>$id,'sales_order_item_id'=>$x->sales_order_item_id,'sku_id'=>$x->sku_id,'quantity_base'=>$qty,'unit_price'=>$unit,'discount_amount'=>$disc,'tax_amount'=>$tx,'line_total'=>$line,'unit_cost'=>$unitCost,'cogs_total'=>$lineCogs,'gross_margin'=>$margin,'source_snapshot'=>json_encode(['goods_receipt_item_id'=>$x->id]),'created_at'=>now(),'updated_at'=>now()]);}DB::table('wh_sales_invoices')->where('id',$id)->update(['subtotal'=>$subtotal,'discount_total'=>$discount,'tax_total'=>$tax,'grand_total'=>$grand,'balance_due'=>$grand,'cogs_total'=>$cogs,'gross_margin'=>$grand-$cogs,'updated_at'=>now()]);$this->event('sales_invoice',$id,'issued',['goods_receipt_id'=>$grId,'grand_total'=>$grand,'cogs_total'=>$cogs],$user->id);return DB::table('wh_sales_invoices')->where('id',$id)->first();});}
 public function postReceipt(array $data,object $user):object{return DB::transaction(function()use($data,$user){$invoice=DB::table('wh_sales_invoices')->lockForUpdate()->where('id',$data['sales_invoice_id'])->whereIn('status',['issued','partially_paid'])->first();if(!$invoice)throw ValidationException::withMessages(['sales_invoice_id'=>'Invoice terbuka tidak ditemukan.']);$amount=(float)$data['amount'];if($amount<=0||$amount>(float)$invoice->balance_due+0.0001)throw ValidationException::withMessages(['amount'=>'Nominal pembayaran melebihi saldo invoice atau tidak valid.']);$key=$data['idempotency_key']??('invoice:'.$invoice->id.':'.($data['reference_number']??Str::uuid()));$old=DB::table('wh_customer_receipts')->where('idempotency_key',$key)->first();if($old)return $old;$id=(string)Str::ulid();DB::table('wh_customer_receipts')->insert(['id'=>$id,'receipt_number'=>$this->number('WH-RCPT'),'warehouse_id'=>$invoice->warehouse_id,'customer_id'=>$invoice->customer_id,'receipt_date'=>$data['receipt_date']??now()->toDateString(),'payment_method'=>$data['payment_method'],'reference_number'=>$data['reference_number']??null,'amount'=>$amount,'status'=>'posted','idempotency_key'=>$key,'posted_by_user_id'=>$user->id,'posted_at'=>now(),'notes'=>$data['notes']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('wh_customer_receipt_allocations')->insert(['id'=>(string)Str::ulid(),'customer_receipt_id'=>$id,'sales_invoice_id'=>$invoice->id,'allocated_amount'=>$amount,'created_at'=>now(),'updated_at'=>now()]);$paid=(float)$invoice->paid_total+$amount;$balance=max(0,(float)$invoice->grand_total-$paid);DB::table('wh_sales_invoices')->where('id',$invoice->id)->update(['paid_total'=>$paid,'balance_due'=>$balance,'status'=>$balance<=0.0001?'paid':'partially_paid','updated_at'=>now()]);$this->event('customer_receipt',$id,'posted',['sales_invoice_id'=>$invoice->id,'amount'=>$amount],$user->id);return DB::table('wh_customer_receipts')->where('id',$id)->first();});}
 public function voidReceipt(string $id,string $reason,object $user):object{return DB::transaction(function()use($id,$reason,$user){$r=DB::table('wh_customer_receipts')->lockForUpdate()->where('id',$id)->where('status','posted')->first();if(!$r)throw ValidationException::withMessages(['receipt'=>'Penerimaan posted tidak ditemukan.']);$alloc=DB::table('wh_customer_receipt_allocations')->where('customer_receipt_id',$id)->first();if($alloc){$inv=DB::table('wh_sales_invoices')->lockForUpdate()->where('id',$alloc->sales_invoice_id)->first();$paid=max(0,(float)$inv->paid_total-(float)$alloc->allocated_amount);$bal=max(0,(float)$inv->grand_total-$paid);DB::table('wh_sales_invoices')->where('id',$inv->id)->update(['paid_total'=>$paid,'balance_due'=>$bal,'status'=>$paid>0?'partially_paid':'issued','updated_at'=>now()]);}DB::table('wh_customer_receipts')->where('id',$id)->update(['status'=>'void','notes'=>trim(($r->notes? $r->notes."\n":'').'VOID: '.$reason),'updated_at'=>now()]);$this->event('customer_receipt',$id,'voided',['reason'=>$reason],$user->id);return DB::table('wh_customer_receipts')->where('id',$id)->first();});}
 public function dashboard(array $warehouseIds):array{$q=DB::table('wh_sales_invoices')->whereIn('warehouse_id',$warehouseIds)->where('status','!=','void');return ['revenue'=>(clone $q)->sum('grand_total'),'receivable'=>(clone $q)->sum('balance_due'),'cogs'=>(clone $q)->sum('cogs_total'),'gross_margin'=>(clone $q)->sum('gross_margin'),'overdue'=>(clone $q)->where('balance_due','>',0)->where('due_date','<',now()->toDateString())->sum('balance_due')];}
 private function resolveUnitCost(string $warehouseId,string $skuId,string $salesOrderId):float{$cost=DB::table('wh_sales_order_reservations as r')->leftJoin('wh_batch_balances as b',function($j){$j->on('b.batch_id','=','r.batch_id')->on('b.warehouse_id','=','r.warehouse_id');})->where('r.sales_order_id',$salesOrderId)->where('r.sku_id',$skuId)->selectRaw('SUM(r.reserved_qty_base * COALESCE(b.average_unit_cost,0))/NULLIF(SUM(r.reserved_qty_base),0) as unit_cost')->value('unit_cost');if($cost!==null)return (float)$cost;return (float)(DB::table('wh_batch_balances')->where('warehouse_id',$warehouseId)->where('sku_id',$skuId)->where('on_hand_qty','>',0)->selectRaw('SUM(inventory_value)/NULLIF(SUM(on_hand_qty),0) as unit_cost')->value('unit_cost')??0);}
 private function number(string $prefix):string{return $prefix.'-'.now()->format('Ymd').'-'.strtoupper(Str::random(6));}private function event(string $type,string $id,string $event,array $payload,?string $actor):void{DB::table('wh_finance_events')->insert(['id'=>(string)Str::ulid(),'document_type'=>$type,'document_id'=>$id,'event_type'=>$event,'payload'=>json_encode($payload),'actor_user_id'=>$actor,'created_at'=>now(),'updated_at'=>now()]);}
}